{"command":"cat <<'EOF' > solve_clique.py
from typing import Dict, List, Any
from problems import Clique
import itertools

def solve(instance: Dict[str, Any]) -> bool:
    Clique.validate(instance)
    n = instance["n"]
    edges_set = {frozenset(e) for e in instance["edges"]}
    k = instance["k"]
    if k <= 0:
        return True
    if k == 1:
        return n >= 1
    if k > n:
        return False
    # check subsets of size k up to n
    for size in range(k, n + 1):
        for subset in itertools.combinations(range(n), size):
            # verify all pairs are edges
            ok = True
            for u, v in itertools.combinations(subset, 2):
                if frozenset((u, v)) not in edges_set:
                    ok = False
                    break
            if ok:
                return True
    return False
EOF"}

